-- Safe Tomas ASIN links (OEM/SKU + color). Review before prod.
INSERT INTO wp_postmeta (post_id, meta_key, meta_value) SELECT 7571, 'amazon_asin', 'B09M724GGT' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM wp_postmeta WHERE post_id=7571 AND meta_key='amazon_asin' AND meta_value<>'');
UPDATE wp_postmeta SET meta_value='B09M724GGT' WHERE post_id=7571 AND meta_key='amazon_asin';
